def test_ghost_visual():
    ghost = GhostVisual('ghost1')
    assert ghost.get_state() == 'inactive'
    ghost.set_state('active')
    assert ghost.get_state() == 'active'
    try:
        ghost.set_state('invalid')
    except ValueError:
        pass
